  def __init__(self, f: Callable[[Value], Value], inner: SOp):
    super().__init__()
    self.f = f
    self.inner = inner

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.inner]

  def __call__(self, xs: Sequence[Value]) -> Sequence[Value]:
    return [self.f(x) for x in self.inner(xs)]


