  def __init__(self, f: Callable[[Value], Value], x: SOp):
    super().__init__()
    self.f = f
    self.x = x

  def __call__(self, xs: Sequence[Value]) -> Sequence[Value]:
    return [self.f(x) for x in self.x(xs)]

