  """Evaluates a RASP expression."""
  if isinstance(expr, RASPExpr):
    return expr(xs)
  elif isinstance(expr, Sequence):
    return [evaluate(e, xs) for e in expr]
  else:
    raise ValueError(f"Unknown expression type: {type(expr)}")


