@dataclasses.dataclass
class MLP(Block):
  """A transformer MLP block."""
  w_in: vectorspace_fns.Linear
  w_out: vectorspace_fns.Linear
  residual_space: Optional[bases.VectorSpaceWithBasis] = None

  def __post_init__(self):
    """Infer residual stream and typecheck subspaces."""
    if self.residual_space is None:
      self.residual_space = bases.join_vector_spaces(self.w_in.input_space,
                                                     self.w_in.output_space,
                                                     self.w_out.input_space,
                                                     self.w_out.output_space)

    assert self.w_in.input_space.issubspace(self.residual_space)
    assert self.w_in.output_space.issubspace(self.residual_space)
    assert self.w_out.input_space.issubspace(self.residual_space)
    assert self.w_out.output_space.issubspace(self.residual_space)

  def apply(self, x: bases.VectorInBasis) -> bases.VectorInBasis:
    assert x in self.residual_space
    # seq_len x input_space
    x = project(self.residual_space, self.w_in.input_space)(x)
    out = self.w_in(x)
    out = relu(out)
    out = self.w_out(out)
    return project(self.w_out.output_space, self.residual_space)(out)


