def _get_attention_heads(block: Block) -> Iterable[AttentionHead]:
  if isinstance(block, AttentionHead):
    yield block
  elif isinstance(block, MultiAttentionHead):
    yield from block.heads()
  elif isinstance(block, SerialComposition):
    for sub_block in block.blocks:
      yield from _get_attention_heads(sub_block)


