def _get_prior_parameters(
    prior: Prior) -> Union[Dict[str, float], float]:
  """Convert a prior to a dictionary of parameters or a float."""
  if isinstance(prior, dist.Distribution):
    return prior
  elif isinstance(prior, Mapping):
    return prior
  elif isinstance(prior, Sequence):
    return prior
  else:
    return prior


def _get_model_prior(
    name: str,
    custom_priors: MutableMapping[str, Prior]) -> Prior:
  """Get the prior for a given name, using custom priors if available."""
  if name in custom_priors:
    return custom_priors[name]
  return _get_default_priors()[name]


def _get_transform_prior(
    name: str,
    transform_name: str,
    custom_priors: MutableMapping[str, Prior]) -> Prior:
  """Get the prior for a given transform name, using custom priors if available."""
  if name in custom_priors:
    return custom_priors[name]
  return _get_transform_default_priors()[transform_name][name]


def _get_media_transforms(
    transform_name: str,
    custom_priors: MutableMapping[str, Prior]) -> TransformFunction:
  """Get the media transform function for a given transform name."""
  if transform_name == "carryover":
    return media_transforms.carryover
  elif transform_name == "adstock":
    return media_transforms.adstock
  elif transform_name == "hill_adstock":
    return media_transforms.hill_adstock
  else:
    raise ValueError(f"Unknown transform name: {transform_name}")


def _get_media_prior(
    name: str,
