def masked_mean(t, mask, dim = 1, eps = 1e-5):
    t = t.masked_fill(~mask, 0.)
    numer = t.sum(dim = dim)
    denom = mask.sum(dim = dim)
    return numer / (denom + eps)

def clip_at_norm_threshold_(feature_norm, max_norm, threshold = None):
    threshold = default(threshold, max_norm)
    return feature_norm / (feature_norm / threshold).clamp(min = 1.)

def masked_normalize(t, dim = 1, eps = 1e-5, mask = None, max_norm = None):
    norm = l2norm(t)
    norm = norm.masked_fill(~mask, 0.) if exists(mask) else norm
    norm = norm.sum(dim = dim, keepdim = True) + eps

    if exists(max_norm):
        norm = clip_at_norm_threshold_(norm, max_norm)

    return (t / norm) * (t.shape[dim] ** 0.5)

