    """ basically a superior form of squeeze-excitation that is attention-esque """

    def __init__(
        self,
        *,
        chan_in,
        chan_out
    ):
        super().__init__()
        self.to_k = nn.Conv2d(chan_in, 1, 1)
        hidden_dim = max(3, chan_out // 2)

        self.net = nn.Sequential(
            nn.Conv2d(chan_in, hidden_dim, 1),
            nn.SiLU(),
            nn.Conv2d(hidden_dim, chan_out, 1),
            nn.Sigmoid()
        )

    def forward(self, x):
        context = self.to_k(x)
        context = context.flatten(2).softmax(dim = -1)
        out = einsum('b n, b c n -> b c', context, x.flatten(2))
        out = out.reshape(*out.shape, 1, 1)
        return self.net(out)

