def split_dataset(self, ds):
    dataset_size = len(ds)
    indices = list(range(dataset_size))
    split_ind = int(dataset_size * (1 - self.split_valid_fraction))

    if self.split_random_seed is not None:
        random.seed(self.split_random_seed)
        random.shuffle(indices)

    train_indices, valid_indices = indices[:split_ind], indices[split_ind:]
    train_sampler, valid_sampler = SubsetRandomSampler(train_indices), SubsetRandomSampler(valid_indices)

    train_ds = Subset(ds, train_indices)
    valid_ds = Subset(ds, valid_indices)

    return train_ds, valid_ds

