        loss = self.forward(batch, unet_number = unet_number)

        self.accelerator.backward(loss)

        optim = getattr(self, f'optim{unet_index}')
        scheduler = getattr(self, f'scheduler{unet_index}')

        if exists(scheduler):
            scheduler.step()

        optim.step()
        optim.zero_grad()

        self.steps[unet_index] += 1

        return loss

    def validate(self, unet_number = None):
