  def __init__(self, keys: SOp, queries: SOp, predicate: Callable[[Value, Value],
                                                                  bool]):
    super().__init__()
    self.keys = keys
    self.queries = queries
    self.predicate = predicate

  @property
  def children(self) -> Sequence[RASPExpr]:
    return [self.keys, self.queries]

  @property
  def name(self) -> str:
    return "select"

  def __call__(self, xs: Sequence[Value]) -> Sequence[Value]:
    keys = self.keys(xs)
    queries = self.queries(xs)
