def evaluate(expr: RASPExpr, xs: Sequence[Value]) -> Value:
  """Evaluates a RASP expression on the given input sequence."""
  if isinstance(expr, TokensType):
    return list(xs)
  elif isinstance(expr, IndicesType):
    return list(range(len(xs)))
  elif isinstance(expr, LengthType):
    return len(xs)
  elif isinstance(expr, Map):
    return [expr.f(x) for x in evaluate(expr.inner, xs)]
  elif isinstance(expr, SequenceMap):
    fst = evaluate(expr.fst, xs)
    snd = evaluate(expr.snd, xs)
    return [expr.f(x, y) for x, y in zip(fst, snd)]
  elif isinstance(expr, Full):
    return [expr.fill] * len(xs)
  elif isinstance(expr, ConstantSOp):
    if expr.check_length and len(expr.value) != len(xs):
      raise ValueError(
          f"ConstantSOp length {len(expr.value)} does not match input length "
          f"{len(xs)}")
    return list(expr.value)
  elif isinstance(expr, Select):
    keys = evaluate(expr.keys, xs)
    queries = evaluate(expr.queries, xs)
    return SelectorValue(
        [[expr.predicate(k, q) for k in keys] for q in queries])
  elif isinstance(expr, ConstantSelector):
    if expr.check_length and len(expr.value.value) != len(xs):
      raise ValueError(
          f"ConstantSelector length {len(expr.value.value)} does not match "
          f"input length {len(xs)}")
    return expr.value
  elif isinstance(expr, SelectorAnd):
    fst = evaluate(expr.fst, xs)
    snd = evaluate(expr.snd, xs)
    return SelectorValue(
        [[a and b for a, b in zip(row_fst, row_snd)]
         for row_fst, row_snd in zip(fst.value, snd.value)])
  elif isinstance(expr, SelectorOr):
    fst = evaluate(expr.fst, xs)
    snd = evaluate(expr.snd, xs)
    return SelectorValue(
        [[a or b for a, b in zip(row_fst, row_snd)]
         for row_fst, row_snd in zip(fst.value, snd.value)])
  elif isinstance(expr, SelectorNot):
    inner = evaluate(expr.inner, xs)
    return SelectorValue([[not b for b in row] for row in inner.value])
  elif isinstance(expr, SelectorWidth):
    selector = evaluate(expr.selector, xs)
    return [sum(row) for row in selector.value]
  elif isinstance(expr, Aggregate):
    selector = evaluate(expr.selector, xs)
    sop = evaluate(expr.sop, xs)
    return [sum(sop[i] for i, b in enumerate(row) if b)
            for row in selector.value]
  else:
    raise ValueError(f"Unknown RASP expression: {expr}")

