def make_sort_unique(vals: rasp.SOp, keys: rasp.SOp) -> rasp.SOp:
  """Returns argsort of `vals` by descending `keys`."""
  select_all = rasp.Select(rasp.indices, rasp.indices,
                           rasp.Comparison.TRUE).named("select_all")
  select_prev = rasp.Select(keys, keys,
                            rasp.Comparison.LEQ).named("select_prev")
  return rasp.Aggregate(select_prev, vals, default=0).named("sort_unique")


def make_sort(vals: rasp.SOp, keys: rasp.SOp, max_seq_len: int) -> rasp.SOp:
  """Returns the values sorted by keys in ascending order."""
  sort_unique = make_sort_unique(vals, keys)
  select_all = rasp.Select(rasp.indices, rasp.indices,
                           rasp.Comparison.TRUE).named("select_all")
  return rasp.Aggregate(select_all, sort_unique).named("sort")


def make_count_less_freq(n: int) -> rasp.SOp:
  """Returns how many tokens appear fewer than n times in the input.

  The output sequence contains this count in each position.

  Example usage:
    count_less = make_count_less_freq(2)
    count_less("aaaabcc")
    >> [2, 2, 2, 2, 2, 2, 2]

  Args:
    n: Integer to compare token frequences to.
  """
  hist = make_hist()
  bools = hist < n
  # Keep only one token per distinct token, using a select-and-aggregate.
  select_all = rasp.Select(rasp.indices, rasp.indices,
                           rasp.Comparison.TRUE).named("select_all")
  return rasp.numerical(rasp.Aggregate(select_all, bools,
                                       default=0)).named("count_less_freq")


