def make_most_frequent() -> rasp.SOp:
  """Returns the most frequent token in the input.

  Example usage:
    most_frequent = make_most_frequent()
    most_frequent("aabbbcc")
    >> ['b', 'b', 'b', 'b', 'b', 'b', 'b']
