class Transformer(Block):
  """A transformer model."""
  blocks: List[Block]

  def __post_init__(self):
    self.residual_space = self.blocks[0].residual_space
    assert all(block.residual_space == self.residual_space
               for block in self.blocks)

  def apply(self, x: bases.VectorInBasis) -> bases.VectorInBasis:
    for block in self.blocks:
      x = x + block.apply(x)
    return x

  @property
  def num_heads(self) -> int:
    return sum(block.num_heads for block in self.blocks)

  def heads(self) -> Iterable[AttentionHead]:
    for block in self.blocks:
      if isinstance(block, AttentionHead):
        yield block
      elif isinstance(block, MultiAttentionHead):
        yield from block.heads()
      elif isinstance(block, MLP):
        pass
      else:
        raise NotImplementedError()

  def as_multi(self) -> "Transformer":
    return self

